package dev.gamersclt.batcaverna.nativeapp;
import android.content.*;
import android.widget.*;
import org.json.*;
/** The same live Epic and Steam offer sources used by the desktop site. */
final class FreeGamesView extends ScrollView {
 private final LinearLayout body,list;private final TextView state;private final Button refresh;private boolean busy;private long updated;private final android.os.Handler handler=new android.os.Handler(android.os.Looper.getMainLooper());private final Runnable tick=new Runnable(){public void run(){if(isAttachedToWindow()&&getWindowVisibility()==VISIBLE){if(System.currentTimeMillis()-updated>=300000)load();handler.postDelayed(this,30000);}}};
 FreeGamesView(Context c){super(c);setVerticalScrollBarEnabled(false);body=new LinearLayout(c);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(16),dp(16),dp(16),dp(24));addView(body);body.addView(NativeSheet.text(c,"Jogos grátis para resgatar",25,0xfff4ecff));state=NativeSheet.text(c,"",13,0xffbaa6d2);body.addView(state);refresh=new Button(c);refresh.setText("Atualizar ofertas");AppStyle.button(refresh,false);body.addView(refresh);refresh.setOnClickListener(v->load());list=new LinearLayout(c);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);load();}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();handler.post(tick);}
 @Override protected void onDetachedFromWindow(){handler.removeCallbacks(tick);super.onDetachedFromWindow();}
 @Override protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);if(handler==null)return;handler.removeCallbacks(tick);if(visibility==VISIBLE&&isAttachedToWindow())handler.post(tick);}
 private void load(){if(busy)return;busy=true;refresh.setEnabled(false);state.setText("Atualizando ofertas…");new AccountRepository(getContext()).freeGames((rows,error)->{busy=false;refresh.setEnabled(true);if(error!=null){state.setText(error);return;}updated=System.currentTimeMillis();list.removeAllViews();JSONObject result=rows.optJSONObject(0);JSONArray current=new JSONArray(),upcoming=new JSONArray(),epic=result.optJSONArray("epic");if(epic!=null)for(int i=0;i<epic.length();i++){JSONObject game=epic.optJSONObject(i);if(game==null)continue;long end=MessageTime.epoch(game.optString("fim")),start=MessageTime.epoch(game.optString("inicio"));if(end>0&&end<=updated)continue;if(start>updated)upcoming.put(game);else if(start>0||game.optBoolean("agora"))current.put(game);else upcoming.put(game);}section("Epic Games • grátis agora",current,"Resgatar na Epic Games",result.optString("epicError"));section("Epic Games • em breve",upcoming,"Ver na Epic Games","");section("Steam • 100% de desconto",result.optJSONArray("steam"),"Resgatar na Steam",result.optString("steamError"));section("Outras lojas oficiais",result.optJSONArray("community"),"Abrir oferta",result.optString("epicError"));state.setText(result.has("steamError")||result.has("epicError")?"Atualização parcial. Confira as lojas abaixo.":"Ofertas atualizadas • "+new java.text.SimpleDateFormat("HH:mm",java.util.Locale.ROOT).format(new java.util.Date()));});}
 private void section(String title,JSONArray games,String action,String error){list.addView(NativeSheet.text(getContext(),title,19,0xffd4b4ff));if(!error.isEmpty()){list.addView(NativeSheet.text(getContext(),error,13,0xffc7b5d8));return;}if(games==null||games.length()==0){list.addView(NativeSheet.text(getContext(),"Nenhuma oferta disponível no momento.",13,0xffa9a0b6));return;}for(int i=0;i<games.length();i++){JSONObject game=games.optJSONObject(i);if(game==null)continue;LinearLayout tile=new LinearLayout(getContext());tile.setOrientation(LinearLayout.VERTICAL);tile.setPadding(dp(12),dp(12),dp(12),dp(12));tile.setBackground(AppStyle.shape(tile,0xff211a2d,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(12));list.addView(tile,lp);ImageView cover=new ImageView(getContext());cover.setScaleType(ImageView.ScaleType.CENTER_CROP);tile.addView(cover,new LinearLayout.LayoutParams(-1,dp(150)));AccountImageLoader.load(cover,game.optString("capa"),game.optString("appid",game.optString("steamAppid",game.optString("url","").replaceFirst(".*?/app/([0-9]+).*","$1"))));tile.addView(NativeSheet.text(getContext(),game.optString("nome","Jogo grátis"),18,0xfff4eeff));String date=game.optString(action.startsWith("Ver")?"inicio":"fim","");if(!date.isEmpty())tile.addView(NativeSheet.text(getContext(),(action.startsWith("Ver")?"Disponível a partir de ":"Disponível até ")+MessageTime.day(date),12,0xffbaa5cd));Button open=new Button(getContext());open.setText(action+" ↗");AppStyle.button(open,true);tile.addView(open);String url=game.optString("url","");open.setEnabled(offerUrl(url));open.setOnClickListener(v->{try{getContext().startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(url)));}catch(ActivityNotFoundException e){Toast.makeText(getContext(),"Não foi possível abrir a loja.",Toast.LENGTH_SHORT).show();}});}}
 static boolean offerUrl(String url){try{java.net.URI u=new java.net.URI(url);return "https".equals(u.getScheme())&&u.getUserInfo()==null&&(u.getPort()==-1||u.getPort()==443)&&java.util.Arrays.asList("store.steampowered.com","store.epicgames.com","www.epicgames.com","store.ubisoft.com","www.gog.com","gog.com","itch.io","www.microsoft.com","www.xbox.com","www.ea.com","us.shop.battle.net").contains(u.getHost());}catch(Exception e){return false;}}
 private int dp(int n){return AppStyle.dp(this,n);}
}
